unsafe fn xmlDictFindEntry(
    mut dict: *const xmlDict,
    mut prefix: *const xmlChar,
    mut name: *const xmlChar,
    mut len: c_int,
    mut hashValue: c_uint,
    mut pfound: *mut c_int,
) -> *mut xmlDictEntry {
    let mask = ((*dict).size.wrapping_sub(1 as size_t)) as c_uint;
    let mut pos = hashValue & mask;
    let table = (*dict).table;
    let mut entry = table.add(pos as usize);

    if (*entry).hashValue == 0 {
        *pfound = 0;
        return entry;
    }

    let mut displ: c_uint = 0;
    let found: c_int;

    if prefix.is_null() {
        loop {
            if (*entry).hashValue == hashValue {
                let entry_name = (*entry).name;
                if strncmp(entry_name as *const c_char, name as *const c_char, len as size_t) == 0
                    && *entry_name.add(len as usize) as c_int == 0
                {
                    found = 1;
                    break;
                }
            }

            displ = displ.wrapping_add(1);
            pos = pos.wrapping_add(1);
            entry = if pos & mask == 0 {
                table
            } else {
                entry.add(1)
            };

            if !((*entry).hashValue != 0 && pos.wrapping_sub((*entry).hashValue) & mask >= displ) {
                found = 0;
                break;
            }
        }
    } else {
        loop {
            if (*entry).hashValue == hashValue && xmlStrQEqual(prefix, name, (*entry).name) != 0 {
                found = 1;
                break;
            }

            displ = displ.wrapping_add(1);
            pos = pos.wrapping_add(1);
            entry = if pos & mask == 0 {
                table
            } else {
                entry.add(1)
            };

            if !((*entry).hashValue != 0 && pos.wrapping_sub((*entry).hashValue) & mask >= displ) {
                found = 0;
                break;
            }
        }
    }

    *pfound = found;
    entry
}

